			title = "A Sign of Hope",
			hint = "Tell the prospector what the chalk-scrawled map reveals.",
			unlock = {
				{ type = "quest", id = 720 },
				{ type = "quest", id = 721 },
			},
			text = [=[A map was found near the ruined dig, with a message scrawled on it in chalk: Hammertoe was being taken to {link:uldaman}Uldaman{/link}. Ryedol had mourned him for dead. Now he understood why the Shadowforge had spared him. They wanted what Hammertoe knew of the titan excavations. The {link:dark-iron-dwarves}Dark Irons{/link} had long sought ways to build stronger golems. Hammertoe had studied the same secrets in order to stop them.]=],
		},
		{
