Add({
	kind = "figure",
	id = "lotwil-veriatus",
	title = "Lotwil Veriatus",
	aliases = { "Lotwil" },
	subtitle = "Mage and Tinker of Kharanos",
	tier = "B",
	region = "badlands",
	npc = { 2921 },
	allegiance = "Gnomes · Kharanos",
	found = "His camp in the Dustbowl",
	pin = { x = 25.9, y = 44.9 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Find the gnomish mage who tests his inventions in the Dustbowl.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Lotwil Veriatus is a {link:gnomes}gnome{/link} who blends alchemy, engineering and arcane magic in the service of his own curiosity. He has come from {link:kharanos}Kharanos{/link} to the {link:badlands}Badlands{/link} to build his greatest work: shackles of elemental binding, which would let a mage command elementals far stronger than any called before. His assistant {link:lucien-tosselwrench}Lucien{/link} and his clumsy mechanical servant, Servo, share his camp. Lotwil is brilliant, absent-minded and cheerfully convinced that every setback is a small one.]=],
		},
		{
			title = "Significance",
			text = [=[Lotwil is a scholar of real renown in the elemental sciences, and even the {link:horde}Horde{/link} of {link:kargath}Kargath{/link} seeks his judgment. He also has a past. Long ago he fought a Dark Iron who twisted his life's work into weapons, and he believed that enemy dead.]=],
		},
		{
			title = "Deeds",
			text = [=[• He studies the rock elementals of the {link:badlands}Badlands{/link} to build his shackles.
• He cools and strengthens his shackles with frost oil and a device called a gyrochronatom.
• He summons a guardian of stone with his finished shackles, which does not go as he planned.
• He knows the marks of the golem-maker Argelmach.]=],
		},
		{
			title = "Unrecorded",
			text = [=[The chronicles do not tell how Lotwil and Argelmach first met, or how the Dark Iron came by the {link:gnomes}gnome{/link}'s work.]=],
		},
	},
	chapters = {
		{
			key = "study-of-the-elements",
			title = "Study of the Elements",
			hint = [=[Gather what the gnome needs from the rock elementals of the Badlands.]=],
			unlock = {
				{ type = "quest", id = 712 },
			},
			text = [=[Shards from the lesser elementals, slabs from the greater, and at last the bracers of rock binding from the greatest of them. Each piece let Lotwil test his spells against the stuff of living rock. Each test went as he predicted. He began to speak of the elementals he would soon control, and how they would put all earlier summonings to shame.]=],
		},
		{
			key = "this-is-going-to-be-hard",
			title = "This Is Going to Be Hard",
			hint = [=[Help the gnome finish his shackles, and deal with what follows.]=],
			unlock = {
				{ type = "quest", id = 778 },
			},
			text = [=[The shackles were done. Lotwil called on {link:lucien-tosselwrench}Lucien{/link} and Servo to bear witness, and he summoned a guardian of elemental stone. It did not obey. When the creature was beaten and his shackles recovered, Lotwil admitted that it had not been the outcome he expected. He could not say what had gone wrong. He was glad, he said, that his magic had been there to send the creature home.]=],
		},
		{
			key = "the-rise-of-the-machines",
			title = "The Rise of the Machines",
			hint = [=[Carry the marked elemental shard from Kargath to the gnome's camp.]=],
			unlock = {
				{ type = "quest", id = 4062 },
				{ type = "quest", id = 4063 },
			},
			text = [=[The shards came from golems in the {link:burning-steppes}Burning Steppes{/link}, and they bore initials. When Lotwil saw them, his face went white. He knew the marks. They belonged to Argelmach, a Dark Iron who had bent Lotwil's own work to evil ends, and whom Lotwil had killed with his own hand years before. When Argelmach's head was brought out of {red:blackrock-depths}Blackrock Depths{/red}, it was not flesh. It was a machine made in Argelmach's image, and Lotwil feared that another would rise to take its place.]=],
		},
