			unlock = {
				{ type = "quest", id = 4081 },
				{ type = "quest", id = 4082 },
			},
			text = [=[The notices went up on the walls of {link:kargath}Kargath{/link} in the warlord's name. Angerforge's men were ruthless killers, responsible for the slaughter of the 109th. Every Anvilrage guardsman, warden and officer in the Depths was to be destroyed. Goretooth promised tributes, and he promised worse to Angerforge.]=],
