			hint = [=[Finish the warlord's operation against the Dark Iron general.]=],
			unlock = {
				{ type = "quest", id = 4132 },
			},
			text = [=[The last operation was the one the warlord had waited for. General Angerforge, the Butcher of {link:blackrock-mountain}Blackrock{/link}, was slain in the Depths. Goretooth called it justice at last, and he gave a medallion of the K.E.F. to the one who had carried it out.]=],
