	id = "thal-trak-proudtusk",
	title = "Thal'trak Proudtusk",
	aliases = { "Thal'trak" },
	subtitle = "Soldier of the K.E.F.",
	tier = "C",
	region = "badlands",
	npc = { 9082 },
	allegiance = "Horde · Kargath Expeditionary Force",
