		{ type = "interact" },
	},
	hint = [=[Speak with the soldier of Kargath who waits for word of his wife.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Thal'trak Proudtusk is a soldier of the {link:kargath}Kargath{/link} Expeditionary Force. His wife, Sha'ni, went with a platoon into the {link:burning-steppes}Burning Steppes{/link} to learn what the Firegut ogres were doing at their rituals. That was weeks ago. No one from her platoon has come back, and {link:warlord-goretooth}Warlord Goretooth{/link} has told Thal'trak to move on. Thal'trak cannot leave his post, and he cannot move on.]=],
		},
		{
			title = "Significance",
			text = [=[Thal'trak is a reminder that the war in the mountain is paid for by ordinary soldiers and the people who wait for them.]=],
		},
		{
			title = "Deeds",
			text = [=[• He sends a searcher to learn what became of Sha'ni.
• He asks for the nose-ring she wore, taken by the {link:ogres}ogre{/link} {link:krom-grul}Krom'Grul{/link}.]=],
		},
	},
	chapters = {
		{
			key = "dreadmaul-rock",
			title = "Dreadmaul Rock",
			hint = "Learn the fate of Thal'trak's wife in the Burning Steppes.",
			unlock = {
				{ type = "quest", id = 3822 },
			},
			text = [=[Sha'ni would not come home. She and Thal'trak had planned to live with her parents in {link:the-hinterlands}The Hinterlands{/link} when their tours were done. All that returned to {link:kargath}Kargath{/link} was her nose-ring, taken back from the {link:ogres}ogre{/link} {link:krom-grul}Krom'Grul{/link} in the caves of {link:dreadmaul-rock}Dreadmaul Rock{/link}.]=],
		},
	},
	mentions = {
		{
			text = "{link:dreadmaul-rock}Dreadmaul Rock{/link}",
			unlock = {
				{ type = "quest", id = 3821 },
			},
		},
		{
			text = "{link:krom-grul}Krom'Grul{/link}",
			unlock = {
				{ type = "quest", id = 3822 },
			},
		},
	},
	bonds = {
		{ id = "sha-ni-proudtusk", name = "Sha'ni Proudtusk", note = "his wife" },
		{ id = "warlord-goretooth", name = "Warlord Goretooth", note = "his commander" },
	},
})

