Add({
	kind = "figure",
	id = "gorn",
	title = "Gorn",
	subtitle = "Orc of Kargath",
	tier = "C",
	region = "badlands",
	npc = { 1068 },
	allegiance = "Horde · Kargath",
	found = "Kargath",
	pin = { x = 2.9, y = 45.6 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Speak with the orc of Kargath who would wipe out a stain on the Horde's honor.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Gorn is an {link:orcs}orc{/link} of {link:kargath}Kargath{/link} who remembers the {link:second-war}Second War{/link} with shame. In that war the {link:horde}Horde{/link} stood allied with {link:deathwing}Deathwing{/link}, and two of the dragon's lieutenants, {link:blacklash}Blacklash{/link} and {link:hematus}Hematus{/link}, still lie bound beneath {link:lethlor-ravine}Lethlor Ravine{/link}. Gorn means to silence the Horde's depraved allies of old, to restore its honor.]=],
		},
		{
			title = "Significance",
			text = [=[Gorn speaks for the new {link:horde}Horde{/link}'s wish to put the crimes of the old behind it. He also speaks for its hard lessons about the {link:ogres}ogres{/link}, who are no longer part of the Horde.]=],
		},
		{
			title = "Deeds",
			text = [=[• He hired {link:boss-tho-grun}Boss Tho'grun{/link}'s ogres to take the Sign of the Earth, and they betrayed him.
• He sends {link:kargath}Kargath{/link}'s fighters to take back the Sign and break the seal of {link:lethlor-ravine}Lethlor{/link}.]=],
		},
	},
	chapters = {
		{
			key = "broken-alliances",
			title = "Broken Alliances",
			hint = [=[Help the orc of Kargath put Deathwing's lieutenants to death.]=],
			unlock = {
				{ type = "quest", id = 793 },
			},
			text = [=[The Sign of the Earth came back to {link:kargath}Kargath{/link}, and the drakes of {link:lethlor-ravine}Lethlor{/link} were freed only to be killed. Gorn saw it as one more step. The black dragonflight still stood with the renegade {link:blackrock-clan}Blackrock orcs{/link}, and both had to be brought to heel or removed. With the drakes dead, Kargath could turn its eyes west, toward {red:blackrock-spire}Blackrock Spire{/red}.]=],
		},
	},
	mentions = {
		{
			text = [=[Broken Alliances, the betrayal of {link:boss-tho-grun}Tho'grun{/link}]=],
			unlock = {
				{ type = "quest", id = 782 },
			},
		},
		{
			text = "Broken Alliances, the drakes slain",
			unlock = {
				{ type = "quest", id = 793 },
			},
		},
		{
			text = "Seal of the Earth",
			unlock = {
				{ type = "quest", id = 795 },
			},
		},
	},
	bonds = {
		{ id = "boss-tho-grun", name = "Boss Tho'grun", note = "betrayed him" },
		{ id = "blacklash", name = "Blacklash", note = "an ally of old he would silence" },
		{ id = "hematus", name = "Hematus", note = "an ally of old he would silence" },
	},
})

